<span class="line"><span style="color:#ABB2BF;">pipe.</span><span style="color:#61AFEF;">incr</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;nonexistent_key&#39;</span><span style="color:#ABB2BF;">)  </span><span style="color:#7F848E;font-style:italic;"># 这会失败，但不影响其他命令</span></span>
